/**
 * The typed envelope, served by the kind routes.
 */
export type Workflow = {
    apiVersion: 'catalog.texera.apache.org/v1';
    kind: ResourceKind;
    metadata: ResourceMetadata;
    spec: WorkflowSpec;
    status?: WorkflowStatus;
};

/**
 * A workflow version's content: a dataflow graph.
 */
export type WorkflowContent = {
    operators: Array<WorkflowOperator>;
    links: Array<WorkflowLink>;
};

/**
 * A link from one operator's output port to another's input port.
 */
export type WorkflowLink = {
    linkID: string;
    source: WorkflowLinkEnd;
    target: WorkflowLinkEnd;
};

export type WorkflowLinkEnd = {
    operatorID: string;
    portID: string;
};

/**
 * An operator instance in a workflow.
 */
export type WorkflowOperator = {
    /**
     * Unique within the workflow, e.g. scan or avg.
     */
    operatorID: string;
    /**
     * An operatorType from the operator registry (list_operators), e.g. CSVFileScan.
     */
    operatorType: string;
    operatorVersion?: string;
    /**
     * Property values following the operator type's JSON Schema. A file property takes a dataset URI dataset://<rid>@<vno>/<path>.
     */
    operatorProperties: {
        [key: string]: unknown;
    };
    /**
     * Defaults to one input port input-0 (none for sources).
     */
    inputPorts?: Array<WorkflowPort>;
    /**
     * Defaults to one output port output-0.
     */
    outputPorts?: Array<WorkflowPort>;
    /**
     * Store this operator's output so it can be read with get_port_result.
     */
    viewResult?: boolean;
    markedForReuse?: boolean;
    isDisabled?: boolean;
    customDisplayName?: string;
};

export type WorkflowPage = {
    items: Array<Workflow>;
    /**
     * Opaque cursor for the next page; absent on the last page.
     */
    nextCursor?: string;
};

